#!/usr/bin/env python3
"""
fix_catalog_v1.py — adds the Card Catalog + Deck Builder as a second build target.

ADDS (new files only; nothing existing is modified)
  src/catalog.src.html      the catalog app (browse, card pages, deck builder,
                            precons, print, archetypes, how-to-read)
  tools/build_catalog.py    builds dist/catalog.html from catalog.xlsx + the game's
                            rules/expansions + the files below
  catalog/content.json      hand-written text (stories, best uses, archetype roles)
  art/back_print.webp       card back for printing (from art/back.png)
  art/back_emblem.webp      emblem for the light, ink-saving back
  art/scans/<id>.webp       27 Dextrous scans at 480x672, named by card id

RUN (repo root)
  python3 fix_catalog_v1.py
  python3 tools/build_catalog.py        # -> dist/catalog.html

Refuses to run twice. Checks prerequisites first. Standard library only.
"""
import base64, os, sys
ROOT = os.path.dirname(os.path.abspath(__file__))
def die(m): sys.exit("[fix_catalog_v1] " + m)

FILES = {
"src/catalog.src.html": "",
"tools/build_catalog.py": "",
"catalog/content.json": "",
"art/back_print.webp": "",
"art/back_emblem.webp": "",
"art/scans/abigail.webp": "",
"art/scans/abigail_the_absent_adjudicat.webp": "",
"art/scans/abigail_voice_of_the_court.webp": "",
"art/scans/daisy.webp": "",
"art/scans/daisy_careless_fool.webp": "",
"art/scans/daisy_the_golden_girl.webp": "",
"art/scans/gatsby.webp": "",
"art/scans/gatsby_doomed_dreamer.webp": "",
"art/scans/gatsby_the_host_of_west_egg.webp": "",
"art/scans/jproctor.webp": "",
"art/scans/jproctor_his_good_name.webp": "",
"art/scans/jproctor_the_accused_husband.webp": "",
"art/scans/lady_macbeth.webp": "",
"art/scans/lady_macbeth_the_haunted_que.webp": "",
"art/scans/lady_macbeth_the_undone.webp": "",
"art/scans/macbeth.webp": "",
"art/scans/macbeth_thane_of_cawdor.webp": "",
"art/scans/macbeth_tyrant_of_dunsinane.webp": "",
"art/scans/mercutio.webp": "",
"art/scans/mercutio_worms_meat.webp": "",
"art/scans/myrtle.webp": "",
"art/scans/myrtle_fallen_ashes.webp": "",
"art/scans/romeo.webp": "",
"art/scans/romeo_fortunes_fool.webp": "",
"art/scans/romeo_husband_of_juliet.webp": "",
"art/scans/tybalt.webp": "",
"art/scans/tybalt_the_prince_of_cats.webp": ""
}

# prerequisites
for p in ("src/game.src.html", "tools/sync_catalog.py"):
    if not os.path.exists(os.path.join(ROOT, p)): die("missing %s — run this from the repo root." % p)
g = open(os.path.join(ROOT, "src/game.src.html"), encoding="utf-8").read()
for anchor in ("const PM = {", "const LIMITS=", "const DECK_ORDER =", "const setName =", "window.EXPANSIONS."):
    if anchor not in g: die("src/game.src.html no longer contains %r; the catalog reads it. Nothing written." % anchor)
s = open(os.path.join(ROOT, "tools/sync_catalog.py"), encoding="utf-8").read()
if "def read_xlsx" not in s or "def table" not in s: die("tools/sync_catalog.py has no read_xlsx/table. Nothing written.")

# refuse to run twice / never overwrite
exist = [p for p in FILES if os.path.exists(os.path.join(ROOT, p))]
if exist:
    if len(exist) == len(FILES): die("already applied (all %d files present). Nothing to do." % len(FILES))
    die("these files already exist, refusing to overwrite:\n  " + "\n  ".join(exist))

for rel, b64 in FILES.items():
    path = os.path.join(ROOT, rel)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "wb") as f: f.write(base64.b64decode(b64))
    print("  + " + rel)
print("[fix_catalog_v1] added %d files. Next:  python3 tools/build_catalog.py" % len(FILES))
